3: import React from 'react';
4: import ReactDOMClient from 'react-dom/client';
5: import type { AppProps } from 'single-spa';
6: import singleSpaReact, { type ReactAppOrParcel } from 'single-spa-react';
7: import type { ComponentDecoratorOptions } from './openmrsComponentDecorator';
8: import { openmrsComponentDecorator } from './openmrsComponentDecorator';
9: 
10: /**
11:  * Creates a single-spa lifecycle object for a React component. The component is
12:  * wrapped with the OpenMRS component decorator which provides standard functionality
13:  * like error boundaries, configuration, and extension support.
14:  *
15:  * @param Component The React component to create a lifecycle for.
16:  * @param options Configuration options for the OpenMRS component decorator.
17:  * @returns A single-spa lifecycle object with bootstrap, mount, and unmount functions.
18:  *
19:  * @example
20:  * ```ts
21:  * import { getLifecycle } from '@openmrs/esm-framework';
22:  * import MyComponent from './MyComponent';
23:  * export const lifecycle = getLifecycle(MyComponent, { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' });
24:  * ```
25:  */
26: export function getLifecycle<T>(Component: ComponentType<T>, options: ComponentDecoratorOptions) {
27:   return singleSpaReact<T>({
28:     React,
29:     ReactDOMClient,
30:     rootComponent: openmrsComponentDecorator<T>(options)(Component) as ComponentType<T & AppProps>,
31:   });
32: }
33: 
34: /**
35:  * Creates a lazy-loading single-spa lifecycle for a React component. The component
36:  * is loaded asynchronously via dynamic import only when it's needed, which helps
37:  * reduce initial bundle size. This is the recommended way to define lifecycles
38:  * for most modules.
39:  *
40:  * @param lazy A function that returns a Promise resolving to a module with the
41:  *   component as its default export (i.e., a dynamic import).
42:  * @param options Configuration options for the OpenMRS component decorator.
43:  * @returns A function that returns a Promise resolving to a single-spa lifecycle object.
44:  *
45:  * @example
46:  * ```ts
47:  * import { getAsyncLifecycle } from '@openmrs/esm-framework';
48:  * const options = { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' };
49:  * export const root = getAsyncLifecycle(() => import('./root.component'), options);
50:  * ```
51:  */
52: export function getAsyncLifecycle<T>(
53:   lazy: () => Promise<{ default: ComponentType<T> }>,
54:   options: ComponentDecoratorOptions,
55: ) {
56:   return () => lazy().then(({ default: Component }) => getLifecycle(Component, options));
57: }
58: 
59: /**
60:  * Creates a single-spa lifecycle for a React component that is already loaded.
61:  * Unlike {@link getAsyncLifecycle}, this wraps a synchronously-available component
62:  * in a Promise to match the expected lifecycle interface. Use this when the
63:  * component doesn't need lazy loading.
