1: import { importDynamic } from '@openmrs/esm-dynamic-loading';
2: import { type LifeCycles } from 'single-spa';
3: import { registerModuleLoad } from '@openmrs/esm-config';
4: 
5: // Couldn't figure out how to express this as an interface
6: type Module = Omit<Record<string, () => LifeCycles | Promise<LifeCycles>>, 'startupApp'> & {
7:   startupApp?: () => unknown;
8: };
9: 
10: /**
11:  * @internal
12:  *
13:  * Used internally to track which apps have had their `startupApp()` initializer called
14:  *
15:  * Values are promises to support asynchronous loading of the same app multiple times
16:  */
17: const initializedApps = new Map<string, Promise<unknown>>();
18: 
19: /**
20:  * This function loads a single-spa Lifecycles from the given app. The Lifecycles should be
21:  * created using `getAsyncLifecycle()` or `getSyncLifecycle()` and exported in the app's
22:  * index.ts file.
23:  * The function is lazy and ensures that the appropriate module is loaded,
24:  * that the module's `startupApp()` is called before the component is loaded. It
25:  * then calls the component function, which should return either a single-spa
26:  * {@link LifeCycles} object or a {@link Promise} that will resolve to such an object.
27:  *
28:  * @param routesAppName The app name of the routes.json file defining the component to load
29:  *
30:  * @param fullComponentName The name of the component to load. Note that this can optionally
31:  * include the appName to load the component from (in the format `${appName}#${componentName}`),
32:  * or omitted to implicitly use routesAppName
33:  *
34:  */
35: export async function loadLifeCycles(routesAppName: string, fullComponentName: string): Promise<LifeCycles> {
36:   const poundIndex = fullComponentName.indexOf('#');
37:   const isNamespaced = poundIndex >= 0;
38:   const appName = isNamespaced ? fullComponentName.substring(0, poundIndex) : routesAppName;
39:   const componentName = isNamespaced ? fullComponentName.substring(poundIndex + 1) : fullComponentName;
40: 
41:   const module = await importDynamic<Module>(appName);
42: 
43:   if (module && Object.hasOwn(module, componentName) && typeof module[componentName] === 'function') {
44:     return initializeApp(appName, module).then(() => module[componentName]());
45:   } else {
46:     if (!module) {
47:       console.warn(`Unknown app ${appName} for ${fullComponentName} defined in ${routesAppName}'s routes.json`);
48:     } else if (module && Object.hasOwn(module, componentName)) {
49:       console.warn(`The export ${fullComponentName}, defined in ${routesAppName}'s routes.json, is not a function`);
50:     } else {
51:       console.warn(
52:         `${appName} does not define a component called "${componentName}", referenced in ${routesAppName}'s routes.json. This cannot be loaded.`,
53:       );
54:     }
55:   }
56: 
57:   return emptyLifecycle;
58: }
59: 
60: const emptyLifecycle: LifeCycles<never> = {
61:   bootstrap() {
62:     return Promise.resolve();
63:   },
64:   mount() {
65:     return Promise.resolve();
66:   },
67:   unmount() {
68:     return Promise.resolve();
69:   },
70: };
71: 
72: /**
73:  * This function can be used to manually initialize an application without waiting for the
74:  * framework to load it. This can sometimes be helpful if the framework doesn't load code
75:  * at the point you think is appropriate.
76:  *
77:  * This will ensure that the module is available and that it's `startupApp()` function (if
78:  * any) will be called. Note that these are only guaranteed to be complete once the Promise
79:  * returned from the function completes.
80:  *
81:  * @param appName The name of the app to initialize
82:  * @param module The loaded code module, if available; if this parameter is omitted, this
83:  *   function will load it.
84:  * @returns a Promise which completes once the app has been loaded and initialized
85:  */
86: async function initializeApp(appName: string, module?: Module) {
87:   if (!(appName in initializedApps)) {
88:     let _module: Module = module ?? (await importDynamic<Module>(appName));
89: 
90:     await (initializedApps[appName] = new Promise((resolve, reject) => {
91:       if (Object.hasOwn(_module, 'startupApp')) {
92:         const startup = _module['startupApp'];
93:         if (typeof startup === 'function') {
94:           return Promise.resolve(startup())
95:             .then(() => {
96:               registerModuleLoad(appName);
97:               resolve(null);
98:             })
99:             .catch(reject);
100:         }
101:       }
102: 
103:       registerModuleLoad(appName);
104:       resolve(null);
105:     }));
106:   } else {
107:     await initializedApps[appName];
108:   }
109: }
